CREATE TABLE public.elections(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), election_key text UNIQUE NOT NULL, name text NOT NULL, type text NOT NULL DEFAULT 'municipal', city_id text NOT NULL REFERENCES public.cities(id), institution_id uuid NOT NULL REFERENCES public.institutions(id), location_id uuid NOT NULL REFERENCES public.locations(id), description text NOT NULL DEFAULT '', starts_at timestamptz NOT NULL, candidacy_ends_at timestamptz NOT NULL, campaign_starts_at timestamptz NOT NULL, debate_at timestamptz NOT NULL, vote_starts_at timestamptz NOT NULL, vote_ends_at timestamptz NOT NULL, count_at timestamptz NOT NULL, status text NOT NULL DEFAULT 'preparation' CHECK(status IN('preparation','candidacies','campaign','vote','counting','completed')), rules jsonb NOT NULL DEFAULT '{"voting_age":18,"candidate_age":18,"civic_min":10,"reputation_min":5,"influence_min":0,"independent_civic_min":10,"membership_days":0,"initial_budget":1200,"organization_funding":600,"budget_cap":3000,"donation_amount":150,"donation_limit":3,"daily_actions":3,"mandate_days":120}', round integer NOT NULL DEFAULT 1, eligible_voters integer NOT NULL DEFAULT 10000 CHECK(eligible_voters>0), participation integer, abstention integer, winner_id uuid, last_npc_day date, closed_at timestamptz, CHECK(starts_at<candidacy_ends_at AND candidacy_ends_at<=campaign_starts_at AND campaign_starts_at<debate_at AND debate_at<vote_starts_at AND vote_starts_at<vote_ends_at AND vote_ends_at<=count_at));
GRANT SELECT ON public.elections TO authenticated; GRANT ALL ON public.elections TO service_role; ALTER TABLE public.elections ENABLE ROW LEVEL SECURITY; CREATE POLICY "elections visible" ON public.elections FOR SELECT TO authenticated USING(true);
CREATE TABLE public.candidacies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), election_id uuid NOT NULL REFERENCES public.elections(id) ON DELETE CASCADE, character_id uuid REFERENCES public.characters(id) ON DELETE CASCADE, npc_id uuid REFERENCES public.social_npcs(id), organization_id uuid REFERENCES public.organizations(id), display_name text NOT NULL, status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','submitted','validated','rejected','withdrawn','completed')), refusal_reason text, submitted_at timestamptz, slogan text NOT NULL DEFAULT '', program jsonb NOT NULL DEFAULT '{"priorities":[],"proposals":[]}', program_score integer NOT NULL DEFAULT 0 CHECK(program_score BETWEEN 0 AND 100), base_reputation integer NOT NULL DEFAULT 0, base_influence integer NOT NULL DEFAULT 0, support integer NOT NULL DEFAULT 20 CHECK(support BETWEEN 0 AND 100), visibility integer NOT NULL DEFAULT 0 CHECK(visibility BETWEEN 0 AND 100), campaign_reputation integer NOT NULL DEFAULT 0 CHECK(campaign_reputation BETWEEN 0 AND 100), budget integer NOT NULL DEFAULT 0 CHECK(budget>=0), donations integer NOT NULL DEFAULT 0, started_at timestamptz, UNIQUE(election_id,character_id), UNIQUE(election_id,npc_id), CHECK((character_id IS NULL)<>(npc_id IS NULL)));
GRANT SELECT ON public.candidacies TO authenticated; GRANT ALL ON public.candidacies TO service_role; ALTER TABLE public.candidacies ENABLE ROW LEVEL SECURITY; CREATE POLICY "own and fictional candidacies" ON public.candidacies FOR SELECT TO authenticated USING(npc_id IS NOT NULL OR EXISTS(SELECT 1 FROM public.characters c WHERE c.id=character_id AND c.user_id=auth.uid()));
CREATE TABLE public.campaign_rules(id text PRIMARY KEY, title text NOT NULL, category text NOT NULL, cost integer NOT NULL DEFAULT 0 CHECK(cost>=0), duration_minutes integer NOT NULL DEFAULT 30 CHECK(duration_minutes>0), energy_cost integer NOT NULL DEFAULT 8 CHECK(energy_cost>=0), support_gain integer NOT NULL DEFAULT 2, visibility_gain integer NOT NULL DEFAULT 3, reputation_gain integer NOT NULL DEFAULT 1, risk integer NOT NULL DEFAULT 15 CHECK(risk BETWEEN 0 AND 100));
GRANT SELECT ON public.campaign_rules TO authenticated; GRANT ALL ON public.campaign_rules TO service_role; ALTER TABLE public.campaign_rules ENABLE ROW LEVEL SECURITY; CREATE POLICY "campaign rules visible" ON public.campaign_rules FOR SELECT TO authenticated USING(true);
CREATE TABLE public.campaign_actions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), candidacy_id uuid NOT NULL REFERENCES public.candidacies(id) ON DELETE CASCADE, character_id uuid REFERENCES public.characters(id) ON DELETE CASCADE, rule_id text NOT NULL REFERENCES public.campaign_rules(id), activity_id uuid UNIQUE REFERENCES public.activities(id) ON DELETE CASCADE, cost integer NOT NULL, support_delta integer NOT NULL, visibility_delta integer NOT NULL, reputation_delta integer NOT NULL, debate_choices jsonb, outcome text, created_at timestamptz NOT NULL DEFAULT public.game_now(), rewarded_at timestamptz);
GRANT SELECT ON public.campaign_actions TO authenticated; GRANT ALL ON public.campaign_actions TO service_role; ALTER TABLE public.campaign_actions ENABLE ROW LEVEL SECURITY; CREATE POLICY "own campaign actions" ON public.campaign_actions FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.characters c WHERE c.id=character_id AND c.user_id=auth.uid()));
CREATE TABLE public.campaign_teams(candidacy_id uuid NOT NULL REFERENCES public.candidacies(id) ON DELETE CASCADE, npc_id uuid NOT NULL REFERENCES public.social_npcs(id), role text NOT NULL CHECK(role IN('direction','communication','terrain','evenements','programme')), skill integer NOT NULL CHECK(skill BETWEEN 0 AND 100), cost integer NOT NULL CHECK(cost>=0), PRIMARY KEY(candidacy_id,role), UNIQUE(candidacy_id,npc_id));
GRANT SELECT ON public.campaign_teams TO authenticated; GRANT ALL ON public.campaign_teams TO service_role; ALTER TABLE public.campaign_teams ENABLE ROW LEVEL SECURITY; CREATE POLICY "own campaign team" ON public.campaign_teams FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.candidacies ca JOIN public.characters c ON c.id=ca.character_id WHERE ca.id=candidacy_id AND c.user_id=auth.uid()));
CREATE TABLE public.election_polls(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), election_id uuid NOT NULL REFERENCES public.elections(id) ON DELETE CASCADE, published_at timestamptz NOT NULL, sample_size integer NOT NULL DEFAULT 800, margin numeric NOT NULL DEFAULT 3.5, estimates jsonb NOT NULL, UNIQUE(election_id,published_at));
GRANT SELECT ON public.election_polls TO authenticated; GRANT ALL ON public.election_polls TO service_role; ALTER TABLE public.election_polls ENABLE ROW LEVEL SECURITY; CREATE POLICY "polls visible" ON public.election_polls FOR SELECT TO authenticated USING(published_at<=public.game_now());
CREATE TABLE public.election_votes(election_id uuid NOT NULL REFERENCES public.elections(id) ON DELETE CASCADE, character_id uuid NOT NULL REFERENCES public.characters(id) ON DELETE CASCADE, candidacy_id uuid NOT NULL REFERENCES public.candidacies(id) ON DELETE CASCADE, voted_at timestamptz NOT NULL DEFAULT public.game_now(), PRIMARY KEY(election_id,character_id));
GRANT SELECT ON public.election_votes TO authenticated; GRANT ALL ON public.election_votes TO service_role; ALTER TABLE public.election_votes ENABLE ROW LEVEL SECURITY; CREATE POLICY "own secret ballot" ON public.election_votes FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.characters c WHERE c.id=character_id AND c.user_id=auth.uid()));
CREATE TABLE public.election_results(election_id uuid NOT NULL REFERENCES public.elections(id) ON DELETE CASCADE, candidacy_id uuid NOT NULL REFERENCES public.candidacies(id) ON DELETE CASCADE, votes integer NOT NULL CHECK(votes>=0), percentage numeric NOT NULL, rank integer NOT NULL, PRIMARY KEY(election_id,candidacy_id));
GRANT SELECT ON public.election_results TO authenticated; GRANT ALL ON public.election_results TO service_role; ALTER TABLE public.election_results ENABLE ROW LEVEL SECURITY; CREATE POLICY "completed results visible" ON public.election_results FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.elections e WHERE e.id=election_id AND e.status='completed'));
CREATE TABLE public.municipal_mandates(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), election_id uuid UNIQUE NOT NULL REFERENCES public.elections(id) ON DELETE CASCADE, candidacy_id uuid NOT NULL REFERENCES public.candidacies(id) ON DELETE CASCADE, city_id text NOT NULL REFERENCES public.cities(id), function text NOT NULL DEFAULT 'Maire', starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, status text NOT NULL DEFAULT 'active' CHECK(status IN('active','ended')), decision_id uuid REFERENCES public.public_decisions(id));
GRANT SELECT ON public.municipal_mandates TO authenticated; GRANT ALL ON public.municipal_mandates TO service_role; ALTER TABLE public.municipal_mandates ENABLE ROW LEVEL SECURITY; CREATE POLICY "municipal mandates visible" ON public.municipal_mandates FOR SELECT TO authenticated USING(true);
ALTER TABLE public.activities ADD COLUMN campaign_action_id uuid REFERENCES public.campaign_actions(id) ON DELETE SET NULL;
ALTER TABLE public.news ADD COLUMN election_id uuid REFERENCES public.elections(id) ON DELETE SET NULL;
CREATE FUNCTION public.election_news(_election uuid,_key text,_title text,_body text,_candidate uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e public.elections; ca public.candidacies; eid uuid; nid uuid; BEGIN SELECT * INTO e FROM public.elections WHERE id=_election; SELECT * INTO ca FROM public.candidacies WHERE id=_candidate; INSERT INTO public.events(event_key,title,description,news_body,city_id,starts_at,scope,category,importance,source_id,location_id,organization_id,target_kind) VALUES('election:'||e.id||':'||_key,_title,_body,_body,e.city_id,public.game_now(),'local','Politique',65,'civitas-matin',e.location_id,ca.organization_id,'city') ON CONFLICT(event_key) DO NOTHING; SELECT id INTO eid FROM public.events WHERE event_key='election:'||e.id||':'||_key; nid:=public.publish_world_event(eid); UPDATE public.news SET election_id=e.id,related_entities=related_entities||jsonb_build_object('political',true) WHERE id=nid; RETURN nid; END $$;
REVOKE ALL ON FUNCTION public.election_news(uuid,text,text,text,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.election_news(uuid,text,text,text,uuid) TO service_role;
CREATE FUNCTION public.refresh_election(_election uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e public.elections; ca public.candidacies; d date; next_status text; total_score numeric; voters integer; player_votes integer; simulated integer; winner uuid; did uuid; issue public.public_issues; proposal jsonb; location uuid; day_start date; score numeric; BEGIN SELECT * INTO e FROM public.elections WHERE id=_election FOR UPDATE; IF NOT FOUND THEN RETURN; END IF; IF e.status='completed' THEN UPDATE public.municipal_mandates SET status='ended' WHERE election_id=e.id AND ends_at<=public.game_now(); RETURN; END IF;
next_status:=CASE WHEN public.game_now()<e.starts_at THEN 'preparation' WHEN public.game_now()<e.campaign_starts_at THEN 'candidacies' WHEN public.game_now()<e.vote_starts_at THEN 'campaign' WHEN public.game_now()<e.vote_ends_at THEN 'vote' WHEN public.game_now()<e.count_at THEN 'counting' ELSE 'completed' END;
IF next_status IS DISTINCT FROM e.status THEN UPDATE public.elections SET status=next_status WHERE id=e.id; PERFORM public.election_news(e.id,'phase:'||next_status,e.name||' — '||CASE next_status WHEN 'candidacies' THEN 'Candidatures ouvertes' WHEN 'campaign' THEN 'La campagne commence' WHEN 'vote' THEN 'Le vote est ouvert' WHEN 'counting' THEN 'Dépouillement en cours' ELSE 'Résultats disponibles' END,'Le calendrier municipal progresse selon le temps du monde CIVITAS.'); INSERT INTO public.notifications(user_id,title,body,world_at) SELECT c.user_id,'Élection municipale',e.name||' — '||next_status,public.game_now() FROM public.candidacies a JOIN public.characters c ON c.id=a.character_id LEFT JOIN public.user_settings s ON s.user_id=c.user_id WHERE a.election_id=e.id AND a.status='validated' AND COALESCE(s.notifications_enabled,true); END IF;
IF public.game_now()>=e.campaign_starts_at THEN day_start:=COALESCE(e.last_npc_day+1,(e.campaign_starts_at AT TIME ZONE 'UTC')::date); FOR d IN SELECT generate_series(day_start::timestamp,LEAST((public.game_now() AT TIME ZONE 'UTC')::date,(e.vote_starts_at AT TIME ZONE 'UTC')::date-1)::timestamp,interval '1 day')::date LOOP
FOR ca IN SELECT * FROM public.candidacies WHERE election_id=e.id AND npc_id IS NOT NULL AND status='validated' ORDER BY id FOR UPDATE LOOP
score:=((hashtextextended(ca.id||':'||d,8)&2147483647)%7)-2; UPDATE public.candidacies SET support=LEAST(100,GREATEST(0,support+score::integer)),visibility=LEAST(100,visibility+2),campaign_reputation=LEAST(100,GREATEST(0,campaign_reputation+CASE WHEN score<0 THEN -1 ELSE 1 END)),budget=GREATEST(0,budget-30),started_at=COALESCE(started_at,e.campaign_starts_at) WHERE id=ca.id; INSERT INTO public.campaign_actions(candidacy_id,rule_id,cost,support_delta,visibility_delta,reputation_delta,outcome,created_at,rewarded_at) VALUES(ca.id,'terrain',30,score::integer,2,1,CASE WHEN score<0 THEN 'Accueil mitigé dans le quartier' ELSE 'Rencontre avec les habitants' END,d::timestamp AT TIME ZONE 'UTC',d::timestamp AT TIME ZONE 'UTC'); END LOOP;
UPDATE public.elections SET last_npc_day=d WHERE id=e.id;
SELECT sum(GREATEST(1,support*0.45+visibility*0.20+base_reputation*0.15+base_influence*0.10+program_score*0.10+((hashtextextended(id||':'||d,9)&2147483647)%11)-5)) INTO total_score FROM public.candidacies WHERE election_id=e.id AND status='validated';
IF total_score>0 THEN INSERT INTO public.election_polls(election_id,published_at,estimates) SELECT e.id,GREATEST(e.campaign_starts_at,d::timestamp AT TIME ZONE 'UTC'),jsonb_agg(jsonb_build_object('candidacy_id',id,'estimate',round(100*GREATEST(1,support*0.45+visibility*0.20+base_reputation*0.15+base_influence*0.10+program_score*0.10+((hashtextextended(id||':'||d,9)&2147483647)%11)-5)/total_score,1))) FROM public.candidacies WHERE election_id=e.id AND status='validated' ON CONFLICT DO NOTHING; IF d=(public.game_now() AT TIME ZONE 'UTC')::date THEN PERFORM public.election_news(e.id,'poll:'||d,'Nouveau sondage — '||e.name,'Échantillon fictif : 800 personnes, marge ±3,5 points. Une estimation, pas un résultat.'); END IF; END IF;
END LOOP; END IF;
IF public.game_now()>=e.count_at THEN
SELECT count(*) INTO player_votes FROM public.election_votes WHERE election_id=e.id; voters:=GREATEST(player_votes,round(e.eligible_voters*(0.48+((hashtextextended(e.id::text,10)&2147483647)%150)/1000.0))::integer); simulated:=GREATEST(0,voters-player_votes);
WITH scores AS(SELECT id,GREATEST(1,support*0.30+visibility*0.15+campaign_reputation*0.15+base_reputation*0.10+base_influence*0.10+program_score*0.15+(SELECT COALESCE(count(*),0) FROM public.campaign_actions a WHERE a.candidacy_id=candidacies.id AND a.rewarded_at IS NOT NULL)*0.5+((hashtextextended(id::text,11)&2147483647)%13)) score FROM public.candidacies WHERE election_id=e.id AND status='validated'), allocations AS(SELECT id,floor(simulated*score/sum(score) OVER())::integer simulated_votes,row_number() OVER(ORDER BY score DESC,id) place FROM scores), tallies AS(SELECT id,simulated_votes+CASE WHEN place=1 THEN simulated-sum(simulated_votes) OVER()::integer ELSE 0 END+(SELECT count(*)::integer FROM public.election_votes v WHERE v.election_id=e.id AND v.candidacy_id=allocations.id) voices FROM allocations)
INSERT INTO public.election_results(election_id,candidacy_id,votes,percentage,rank) SELECT e.id,id,voices,round(100.0*voices/GREATEST(1,voters),2),row_number() OVER(ORDER BY voices DESC,id)::integer FROM tallies ON CONFLICT DO NOTHING;
SELECT candidacy_id INTO winner FROM public.election_results WHERE election_id=e.id AND rank=1; IF winner IS NULL THEN UPDATE public.elections SET status='completed',closed_at=public.game_now(),participation=0,abstention=eligible_voters WHERE id=e.id; RETURN; END IF;
SELECT * INTO ca FROM public.candidacies WHERE id=winner; proposal:=ca.program->'proposals'->0; SELECT * INTO issue FROM public.public_issues WHERE city_id=e.city_id AND id::text=proposal->>'issue_id'; location:=COALESCE(issue.location_id,e.location_id);
INSERT INTO public.public_decisions(decision_key,institution_id,city_id,district_id,location_id,issue_id,title,description,category,decided_at,consequences) VALUES('election:'||e.id,e.institution_id,e.city_id,(SELECT district_id FROM public.locations WHERE id=location),location,issue.id,'Mandat municipal — '||COALESCE(proposal->>'title','Priorité municipale'),ca.display_name||' est élu. Projet retenu : '||COALESCE(proposal->>'description','Amélioration des services locaux')||'. Coût et délai sont des estimations du programme, pas un prélèvement bancaire.','Vie locale',public.game_now(),jsonb_build_object('project',COALESCE(proposal->>'title','Programme municipal'),'state','projet_municipal')) ON CONFLICT(decision_key) DO NOTHING RETURNING id INTO did;
IF issue.id IS NOT NULL AND issue.status<>'resolved' THEN UPDATE public.public_issues SET status='studying',stage=2,appeared_at=public.game_now()-2*stage_hours*interval '1 hour' WHERE id=issue.id; INSERT INTO public.issue_history(issue_id,status,description) VALUES(issue.id,'studying','Le projet du nouveau mandat municipal est à l’étude.') ON CONFLICT DO NOTHING; END IF;
INSERT INTO public.municipal_mandates(election_id,candidacy_id,city_id,starts_at,ends_at,decision_id) VALUES(e.id,winner,e.city_id,public.game_now(),public.game_now()+COALESCE((e.rules->>'mandate_days')::integer,120)*interval '1 day',did) ON CONFLICT DO NOTHING;
UPDATE public.elections SET winner_id=winner,status='completed',closed_at=public.game_now(),participation=voters,abstention=GREATEST(0,eligible_voters-voters) WHERE id=e.id;
FOR ca IN SELECT * FROM public.candidacies WHERE election_id=e.id AND character_id IS NOT NULL AND status='validated' ORDER BY character_id LOOP PERFORM public.award_political(ca.character_id,'election:'||e.id,'election',CASE WHEN ca.id=winner THEN 8 ELSE 2 END,CASE WHEN ca.id=winner THEN 5 ELSE 1 END,0,0,'Résultat municipal'); END LOOP;
UPDATE public.candidacies SET status='completed' WHERE election_id=e.id AND status='validated'; PERFORM public.election_news(e.id,'result',e.name||' — résultats', (SELECT display_name FROM public.candidacies WHERE id=winner)||' remporte le mandat municipal. La décision locale est enregistrée.',winner);
END IF; END $$;
REVOKE ALL ON FUNCTION public.refresh_election(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.refresh_election(uuid) TO service_role;
CREATE FUNCTION public.election_state() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid; c public.characters; eid uuid; BEGIN cid:=public.prepare_daily_life(); SELECT * INTO c FROM public.characters WHERE id=cid; FOR eid IN SELECT id FROM public.elections WHERE city_id=c.city_id ORDER BY id LOOP PERFORM public.refresh_election(eid); END LOOP; RETURN jsonb_build_object('world_now',public.game_now(),'character_id',cid,'city_id',c.city_id,'city_name',(SELECT name FROM public.cities WHERE id=c.city_id),'age',c.age,'energy',(SELECT energy FROM public.characters WHERE id=cid),'civic',(SELECT COALESCE(engagement,0) FROM public.civic_stats WHERE character_id=cid),'stats',COALESCE((SELECT to_jsonb(s) FROM public.political_stats s WHERE character_id=cid),'{"reputation":0,"influence":0}'),'rules',(SELECT COALESCE(jsonb_agg(r),'[]') FROM public.campaign_rules r),'elections',(SELECT COALESCE(jsonb_agg(to_jsonb(e)||jsonb_build_object('location',(SELECT to_jsonb(l) FROM public.locations l WHERE id=e.location_id),'voted',EXISTS(SELECT 1 FROM public.election_votes v WHERE v.election_id=e.id AND v.character_id=cid),'candidates',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',a.id,'display_name',a.display_name,'npc_id',a.npc_id,'organization_id',a.organization_id,'organization_name',(SELECT name FROM public.organizations WHERE id=a.organization_id),'status',a.status,'slogan',a.slogan,'program',a.program,'support',a.support,'visibility',a.visibility,'campaign_reputation',a.campaign_reputation,'base_reputation',a.base_reputation,'base_influence',a.base_influence,'mine',a.character_id=cid,'refusal_reason',CASE WHEN a.character_id=cid THEN a.refusal_reason END,'budget',CASE WHEN a.character_id=cid THEN a.budget END,'started_at',a.started_at,'donations',CASE WHEN a.character_id=cid THEN a.donations END)),'[]') FROM public.candidacies a WHERE a.election_id=e.id AND (a.status IN('validated','completed') OR a.character_id=cid)),'polls',(SELECT COALESCE(jsonb_agg(p ORDER BY p.published_at DESC),'[]') FROM public.election_polls p WHERE p.election_id=e.id AND p.published_at<=public.game_now()),'results',(SELECT COALESCE(jsonb_agg(r ORDER BY r.rank),'[]') FROM public.election_results r WHERE r.election_id=e.id AND e.status='completed'),'mandate',(SELECT to_jsonb(m) FROM public.municipal_mandates m WHERE m.election_id=e.id)) ORDER BY e.starts_at DESC),'[]') FROM public.elections e WHERE e.city_id=c.city_id),'actions',(SELECT COALESCE(jsonb_agg(to_jsonb(a)||jsonb_build_object('activity',(SELECT to_jsonb(ac) FROM public.activities ac WHERE ac.id=a.activity_id)) ORDER BY a.created_at DESC),'[]') FROM public.campaign_actions a WHERE a.character_id=cid),'team',(SELECT COALESCE(jsonb_agg(to_jsonb(t)||jsonb_build_object('name',n.first_name||' '||n.last_name,'reputation',n.reputation)),'[]') FROM public.campaign_teams t JOIN public.candidacies a ON a.id=t.candidacy_id JOIN public.social_npcs n ON n.id=t.npc_id WHERE a.character_id=cid),'recruits',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',n.id,'name',n.first_name||' '||n.last_name,'reputation',n.reputation,'skill',LEAST(100,30+n.influence),'cost',100+n.reputation*2,'location',to_jsonb(l),'relation',(SELECT score FROM public.social_relations r WHERE r.character_id=cid AND r.npc_id=n.id))),'[]') FROM public.social_npcs n JOIN public.locations l ON l.id=n.location_id WHERE n.city_id=c.city_id),'organizations',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',o.id,'name',o.name,'joined_at',m.joined_at)),'[]') FROM public.memberships m JOIN public.organizations o ON o.id=m.organization_id WHERE m.character_id=cid AND m.status='active' AND o.kind IN('party','movement') AND EXISTS(SELECT 1 FROM public.political_branches b WHERE b.organization_id=o.id AND b.city_id=c.city_id)),'issues',(SELECT COALESCE(jsonb_agg(jsonb_build_object('id',i.id,'title',i.title,'category',i.category)),'[]') FROM public.public_issues i WHERE city_id=c.city_id)); END $$;
REVOKE ALL ON FUNCTION public.election_state() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.election_state() TO authenticated;
CREATE FUNCTION public.submit_candidacy(_election_id uuid,_organization_id uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid; c public.characters; e public.elections; st public.political_stats; engagement integer; reason text; aid uuid; BEGIN cid:=public.prepare_daily_life(); SELECT * INTO c FROM public.characters WHERE id=cid; PERFORM public.refresh_election(_election_id); SELECT * INTO e FROM public.elections WHERE id=_election_id FOR UPDATE; IF NOT FOUND OR e.city_id<>c.city_id OR public.game_now()<e.starts_at OR public.game_now()>=e.candidacy_ends_at THEN RAISE EXCEPTION 'Candidatures fermées ou autre ville'; END IF; IF EXISTS(SELECT 1 FROM public.candidacies WHERE election_id=e.id AND character_id=cid) THEN RAISE EXCEPTION 'Une seule candidature par élection'; END IF; SELECT * INTO st FROM public.political_stats WHERE character_id=cid; SELECT COALESCE(engagement,0) INTO engagement FROM public.civic_stats WHERE character_id=cid;
reason:=CASE WHEN c.age<COALESCE((e.rules->>'candidate_age')::integer,18) THEN 'Âge minimum de candidature non atteint' WHEN COALESCE(engagement,0)<COALESCE((e.rules->>CASE WHEN _organization_id IS NULL THEN 'independent_civic_min' ELSE 'civic_min' END)::integer,10) THEN 'Engagement citoyen insuffisant' WHEN COALESCE(st.reputation,0)<COALESCE((e.rules->>'reputation_min')::integer,5) THEN 'Réputation politique insuffisante' WHEN COALESCE(st.influence,0)<COALESCE((e.rules->>'influence_min')::integer,0) THEN 'Influence politique insuffisante' WHEN _organization_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.memberships m JOIN public.organizations o ON o.id=m.organization_id WHERE m.character_id=cid AND m.organization_id=_organization_id AND m.status='active' AND o.kind IN('party','movement') AND m.joined_at<=public.game_now()-COALESCE((e.rules->>'membership_days')::integer,0)*interval '1 day' AND EXISTS(SELECT 1 FROM public.political_branches b WHERE b.organization_id=o.id AND b.city_id=c.city_id)) THEN 'Adhésion ou ancienneté locale insuffisante' END;
INSERT INTO public.candidacies(election_id,character_id,organization_id,display_name,status,refusal_reason,submitted_at,base_reputation,base_influence,campaign_reputation,budget) VALUES(e.id,cid,_organization_id,c.first_name||' '||c.last_name,CASE WHEN reason IS NULL THEN 'validated' ELSE 'rejected' END,reason,public.game_now(),COALESCE(st.reputation,0),COALESCE(st.influence,0),COALESCE(st.reputation,0),CASE WHEN reason IS NULL THEN LEAST(COALESCE((e.rules->>'budget_cap')::integer,3000),COALESCE((e.rules->>'initial_budget')::integer,1200)+CASE WHEN _organization_id IS NULL THEN 0 ELSE COALESCE((e.rules->>'organization_funding')::integer,600) END) ELSE 0 END) RETURNING id INTO aid;
INSERT INTO public.notifications(user_id,title,body,world_at) VALUES(c.user_id,CASE WHEN reason IS NULL THEN 'Candidature validée' ELSE 'Candidature refusée' END,COALESCE(reason,e.name),public.game_now()); RETURN aid; END $$;
REVOKE ALL ON FUNCTION public.submit_candidacy(uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.submit_candidacy(uuid,uuid) TO authenticated;
CREATE FUNCTION public.save_candidate_program(_candidacy_id uuid,_slogan text,_program jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid; ca public.candidacies; e public.elections; p jsonb; priority text; score integer:=0; BEGIN cid:=public.prepare_daily_life(); SELECT * INTO ca FROM public.candidacies WHERE id=_candidacy_id AND character_id=cid FOR UPDATE; IF NOT FOUND OR ca.status<>'validated' OR ca.started_at IS NOT NULL THEN RAISE EXCEPTION 'Programme verrouillé ou candidature inaccessible'; END IF; SELECT * INTO e FROM public.elections WHERE id=ca.election_id FOR UPDATE; IF public.game_now()>=e.vote_starts_at THEN RAISE EXCEPTION 'Programme fermé'; END IF; _slogan:=btrim(COALESCE(_slogan,'')); IF length(_slogan)<1 OR length(_slogan)>100 OR _slogan!~'^[[:alnum:][:space:]''’.,!?;:()—–-]+$' THEN RAISE EXCEPTION 'Slogan : 1 à 100 caractères, lettres et ponctuation simple'; END IF;
IF jsonb_typeof(_program->'priorities') IS DISTINCT FROM 'array' OR jsonb_array_length(_program->'priorities')<>3 OR jsonb_typeof(_program->'proposals') IS DISTINCT FROM 'array' OR jsonb_array_length(_program->'proposals')<1 OR jsonb_array_length(_program->'proposals')>10 THEN RAISE EXCEPTION 'Trois priorités et une à dix propositions requises'; END IF;
IF (SELECT count(DISTINCT value) FROM jsonb_array_elements_text(_program->'priorities'))<>3 THEN RAISE EXCEPTION 'Priorités distinctes requises'; END IF;
FOR priority IN SELECT jsonb_array_elements_text(_program->'priorities') LOOP IF priority NOT IN('Économie','Emploi','Logement','Transports','Éducation','Environnement','Sécurité','Culture','Urbanisme','Services publics') THEN RAISE EXCEPTION 'Priorité inconnue'; END IF; END LOOP;
FOR p IN SELECT jsonb_array_elements(_program->'proposals') LOOP IF length(btrim(COALESCE(p->>'title','')))<3 OR length(p->>'title')>100 OR length(btrim(COALESCE(p->>'description','')))<10 OR length(p->>'description')>600 OR NOT (_program->'priorities' ? COALESCE(p->>'category','')) OR COALESCE(p->>'cost','')!~'^[0-9]{1,9}$' OR COALESCE(p->>'months','')!~'^[0-9]{1,3}$' OR COALESCE(p->>'impact','')!~'^[0-9]{1,2}$' OR (p->>'months')::integer NOT BETWEEN 1 AND 120 OR (p->>'impact')::integer NOT BETWEEN 1 AND 20 THEN RAISE EXCEPTION 'Proposition invalide : titre, description, priorité, coût, délai 1–120, impact 1–20'; END IF; IF COALESCE(p->>'issue_id','')<>'' AND NOT EXISTS(SELECT 1 FROM public.public_issues WHERE id::text=p->>'issue_id' AND city_id=e.city_id) THEN RAISE EXCEPTION 'Problème d’une autre ville'; END IF; score:=score+10+CASE WHEN COALESCE(p->>'issue_id','')<>'' THEN 5 ELSE 0 END; END LOOP;
UPDATE public.candidacies SET slogan=_slogan,program=_program,program_score=LEAST(100,40+score) WHERE id=ca.id; END $$;
REVOKE ALL ON FUNCTION public.save_candidate_program(uuid,text,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.save_candidate_program(uuid,text,jsonb) TO authenticated;
CREATE FUNCTION public.manage_campaign(_candidacy_id uuid,_command text,_npc_id uuid DEFAULT NULL,_role text DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid; ca public.candidacies; e public.elections; n public.social_npcs; cost integer; BEGIN cid:=public.prepare_daily_life(); SELECT * INTO ca FROM public.candidacies WHERE id=_candidacy_id AND character_id=cid FOR UPDATE; IF NOT FOUND OR ca.status<>'validated' THEN RAISE EXCEPTION 'Candidature inaccessible'; END IF; SELECT * INTO e FROM public.elections WHERE id=ca.election_id FOR UPDATE; IF public.game_now()>=e.vote_starts_at THEN RAISE EXCEPTION 'Campagne fermée'; END IF;
IF _command='launch' THEN IF ca.started_at IS NOT NULL OR length(ca.slogan)=0 OR jsonb_array_length(ca.program->'priorities')<>3 THEN RAISE EXCEPTION 'Complétez le programme ou campagne déjà lancée'; END IF; UPDATE public.candidacies SET started_at=public.game_now() WHERE id=ca.id; PERFORM public.election_news(e.id,'launch:'||ca.id,ca.display_name||' lance sa campagne',ca.slogan,ca.id);
ELSIF _command='recruit' THEN SELECT * INTO n FROM public.social_npcs WHERE id=_npc_id AND city_id=e.city_id; IF NOT FOUND OR _role IS NULL OR _role NOT IN('direction','communication','terrain','evenements','programme') THEN RAISE EXCEPTION 'Recrutement inaccessible'; END IF; IF NOT EXISTS(SELECT 1 FROM public.social_relations WHERE character_id=cid AND npc_id=n.id AND score>=5) THEN RAISE EXCEPTION 'Rencontrez ce contact avant de le recruter'; END IF; cost:=100+n.reputation*2; IF ca.budget<cost THEN RAISE EXCEPTION 'Budget insuffisant'; END IF; INSERT INTO public.campaign_teams VALUES(ca.id,n.id,_role,LEAST(100,30+n.influence),cost); UPDATE public.candidacies SET budget=budget-cost WHERE id=ca.id;
ELSIF _command='donation' THEN IF ca.donations>=COALESCE((e.rules->>'donation_limit')::integer,3) THEN RAISE EXCEPTION 'Limite de dons atteinte'; END IF; IF NOT EXISTS(SELECT 1 FROM public.campaign_actions WHERE candidacy_id=ca.id AND rewarded_at IS NOT NULL) THEN RAISE EXCEPTION 'Une action terminée est nécessaire'; END IF; UPDATE public.candidacies SET donations=donations+1,budget=LEAST(COALESCE((e.rules->>'budget_cap')::integer,3000),budget+COALESCE((e.rules->>'donation_amount')::integer,150)) WHERE id=ca.id;
ELSIF _command='withdraw' THEN IF EXISTS(SELECT 1 FROM public.activities a JOIN public.campaign_actions ac ON ac.activity_id=a.id WHERE ac.candidacy_id=ca.id AND a.status='running') THEN RAISE EXCEPTION 'Terminez l’activité'; END IF; UPDATE public.candidacies SET status='withdrawn' WHERE id=ca.id; ELSE RAISE EXCEPTION 'Commande inconnue'; END IF; END $$;
REVOKE ALL ON FUNCTION public.manage_campaign(uuid,text,uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.manage_campaign(uuid,text,uuid,text) TO authenticated;
CREATE FUNCTION public.start_campaign_action(_candidacy_id uuid,_rule_id text,_choices jsonb DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid; ca public.candidacies; e public.elections; r public.campaign_rules; aid uuid; action uuid; t timestamptz:=public.game_now(); start_at timestamptz; lid uuid; bonus integer; risk integer; sg integer; vg integer; rg integer; BEGIN cid:=public.prepare_daily_life(); SELECT * INTO ca FROM public.candidacies WHERE id=_candidacy_id FOR UPDATE; IF NOT FOUND OR ca.status<>'validated' OR ca.started_at IS NULL THEN RAISE EXCEPTION 'Campagne inactive'; END IF; SELECT * INTO e FROM public.elections WHERE id=ca.election_id FOR UPDATE; IF e.city_id<>(SELECT city_id FROM public.characters WHERE id=cid) OR t<e.campaign_starts_at OR t>=e.vote_starts_at THEN RAISE EXCEPTION 'Hors période de campagne locale'; END IF; SELECT * INTO r FROM public.campaign_rules WHERE id=_rule_id; IF NOT FOUND THEN RAISE EXCEPTION 'Action inconnue'; END IF; IF r.id<>'debate' AND ca.character_id IS DISTINCT FROM cid THEN RAISE EXCEPTION 'Rejoignez cette campagne par une action de terrain uniquement'; END IF;
IF (SELECT count(*) FROM public.campaign_actions WHERE character_id=cid AND created_at::date=t::date)>=COALESCE((e.rules->>'daily_actions')::integer,3) THEN RAISE EXCEPTION 'Limite quotidienne de campagne atteinte'; END IF;
IF r.id='debate' THEN IF ca.character_id IS DISTINCT FROM cid THEN RAISE EXCEPTION 'Débat réservé au candidat'; END IF; IF EXISTS(SELECT 1 FROM public.campaign_actions WHERE candidacy_id=ca.id AND rule_id='debate') THEN RAISE EXCEPTION 'Débat déjà réservé'; END IF; IF jsonb_typeof(_choices) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(_choices))<>3 OR EXISTS(SELECT 1 FROM jsonb_each_text(_choices) x WHERE x.key NOT IN('Transports','Logement','Environnement') OR x.value NOT IN('prioritaire','progressif','maintien')) THEN RAISE EXCEPTION 'Trois positions de débat requises'; END IF; start_at:=e.debate_at; IF t>start_at+interval '30 minutes' THEN RAISE EXCEPTION 'Débat terminé'; END IF; lid:=e.location_id; ELSE start_at:=t; SELECT location_id INTO lid FROM public.character_positions WHERE character_id=cid; END IF;
IF start_at+r.duration_minutes*interval '1 minute'>e.vote_starts_at THEN RAISE EXCEPTION 'Durée incompatible avec le vote'; END IF; IF (SELECT energy FROM public.characters WHERE id=cid)<r.energy_cost THEN RAISE EXCEPTION 'Énergie insuffisante'; END IF; IF ca.budget<r.cost THEN RAISE EXCEPTION 'Budget de campagne insuffisant'; END IF; IF EXISTS(SELECT 1 FROM public.activities WHERE character_id=cid AND status IN('planned','running') AND start_time<start_at+r.duration_minutes*interval '1 minute' AND end_time>start_at) THEN RAISE EXCEPTION 'Cette action chevauche votre agenda'; END IF;
bonus:=LEAST(3,(SELECT COALESCE(sum(skill),0)/80 FROM public.campaign_teams WHERE candidacy_id=ca.id))::integer; risk:=CASE WHEN random()*100<r.risk THEN -r.support_gain-1 ELSE 0 END; sg:=r.support_gain+bonus+risk; vg:=r.visibility_gain+CASE WHEN risk<0 THEN -5 ELSE bonus END; rg:=r.reputation_gain+CASE WHEN risk<0 THEN -2 ELSE 0 END;
IF r.id='debate' THEN sg:=sg+(SELECT count(*)::integer FROM jsonb_each_text(_choices) x WHERE ca.program->'priorities' ? x.key AND x.value='prioritaire'); END IF;
INSERT INTO public.campaign_actions(candidacy_id,character_id,rule_id,cost,support_delta,visibility_delta,reputation_delta,debate_choices,outcome) VALUES(ca.id,cid,r.id,r.cost,sg,vg,rg,_choices,CASE WHEN risk<0 THEN 'Accueil mitigé : le soutien recule' ELSE 'Mobilisation positive' END) RETURNING id INTO action;
INSERT INTO public.activities(character_id,type,title,start_time,end_time,location_id,energy_cost,status,campaign_action_id,source_key) VALUES(cid,'campaign',r.title||' — '||ca.display_name,start_at,start_at+r.duration_minutes*interval '1 minute',lid,r.energy_cost,'planned',action,'campaign:'||action) RETURNING id INTO aid; UPDATE public.campaign_actions SET activity_id=aid WHERE id=action; UPDATE public.candidacies SET budget=budget-r.cost WHERE id=ca.id;
IF r.id<>'debate' THEN PERFORM public.start_life_activity(_activity_id=>aid); END IF; RETURN aid; END $$;
REVOKE ALL ON FUNCTION public.start_campaign_action(uuid,text,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.start_campaign_action(uuid,text,jsonb) TO authenticated;
CREATE FUNCTION public.campaign_activity_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ac public.campaign_actions; e public.elections; BEGIN IF NEW.type<>'campaign' THEN RETURN NEW; END IF; SELECT * INTO ac FROM public.campaign_actions WHERE id=NEW.campaign_action_id AND character_id=NEW.character_id; IF NOT FOUND THEN RAISE EXCEPTION 'Réservez une action de campagne'; END IF; IF NEW.status='running' AND (TG_OP='INSERT' OR OLD.status IS DISTINCT FROM 'running') THEN SELECT el.* INTO e FROM public.elections el JOIN public.candidacies ca ON ca.election_id=el.id WHERE ca.id=ac.candidacy_id AND ca.status='validated'; IF NOT FOUND OR public.game_now()<e.campaign_starts_at OR public.game_now()>=e.vote_starts_at THEN RAISE EXCEPTION 'Campagne fermée'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER campaign_guard BEFORE INSERT OR UPDATE OF status ON public.activities FOR EACH ROW EXECUTE FUNCTION public.campaign_activity_guard(); REVOKE ALL ON FUNCTION public.campaign_activity_guard() FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.campaign_activity_reward() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ac public.campaign_actions; ca public.candidacies; t public.campaign_teams; BEGIN IF NEW.type='campaign' AND OLD.status='running' AND NEW.status='completed' AND NEW.end_time<=public.game_now() THEN UPDATE public.campaign_actions SET rewarded_at=public.game_now() WHERE id=NEW.campaign_action_id AND rewarded_at IS NULL RETURNING * INTO ac; IF NOT FOUND THEN RETURN NEW; END IF; UPDATE public.candidacies SET support=LEAST(100,GREATEST(0,support+ac.support_delta)),visibility=LEAST(100,GREATEST(0,visibility+ac.visibility_delta)),campaign_reputation=LEAST(100,GREATEST(0,campaign_reputation+ac.reputation_delta)) WHERE id=ac.candidacy_id RETURNING * INTO ca; PERFORM public.award_political(NEW.character_id,'campaign:'||ac.id,'campaign',GREATEST(0,ac.reputation_delta),1,2,1,NEW.title); FOR t IN SELECT * FROM public.campaign_teams WHERE candidacy_id=ca.id LOOP INSERT INTO public.social_relations(character_id,npc_id,score,status,met_at,last_interaction) VALUES(NEW.character_id,t.npc_id,5,'acquaintance',public.game_now(),public.game_now()) ON CONFLICT(character_id,npc_id) DO UPDATE SET score=LEAST(100,social_relations.score+2),last_interaction=public.game_now(); END LOOP; IF ac.rule_id='debate' THEN PERFORM public.election_news(ca.election_id,'debate:'||ac.id,'Débat municipal — '||ca.display_name,ac.outcome,ca.id); END IF; INSERT INTO public.notifications(user_id,title,body,world_at) SELECT user_id,'Action de campagne terminée',NEW.title||' : '||ac.outcome,public.game_now() FROM public.characters WHERE id=NEW.character_id; END IF; RETURN NEW; END $$;
CREATE TRIGGER campaign_reward AFTER UPDATE OF status ON public.activities FOR EACH ROW EXECUTE FUNCTION public.campaign_activity_reward(); REVOKE ALL ON FUNCTION public.campaign_activity_reward() FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.cast_election_vote(_election_id uuid,_candidacy_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid; c public.characters; e public.elections; BEGIN cid:=public.prepare_daily_life(); SELECT * INTO c FROM public.characters WHERE id=cid; PERFORM public.refresh_election(_election_id); SELECT * INTO e FROM public.elections WHERE id=_election_id FOR UPDATE; IF NOT FOUND OR e.city_id<>c.city_id OR c.age<COALESCE((e.rules->>'voting_age')::integer,18) OR public.game_now()<e.vote_starts_at OR public.game_now()>=e.vote_ends_at THEN RAISE EXCEPTION 'Vote fermé ou conditions non remplies'; END IF; IF EXISTS(SELECT 1 FROM public.election_votes WHERE election_id=e.id AND character_id=cid) THEN RAISE EXCEPTION 'Votre vote est déjà enregistré et ne peut plus être modifié'; END IF; IF NOT EXISTS(SELECT 1 FROM public.candidacies WHERE id=_candidacy_id AND election_id=e.id AND status='validated') THEN RAISE EXCEPTION 'Candidat absent du bulletin'; END IF; INSERT INTO public.election_votes VALUES(e.id,cid,_candidacy_id,public.game_now()); INSERT INTO public.notifications(user_id,title,body,world_at) VALUES(c.user_id,'Vote enregistré','Votre choix reste privé et définitif.',public.game_now()); END $$;
REVOKE ALL ON FUNCTION public.cast_election_vote(uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.cast_election_vote(uuid,uuid) TO authenticated;